create or replace function app.financial_report_profit_loss_breakdown(p_report_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare r public.financial_reports%rowtype;fp public.financial_periods%rowtype;v_pay numeric:=0;v_ref numeric:=0;v_rev numeric:=0;v_hpp numeric:=0;v_agent numeric:=0;v_partner numeric:=0;v_marketing numeric:=0;v_payment numeric:=0;v_opex numeric:=0;v_tax numeric:=0;v_other numeric:=0;v_exp numeric:=0;v_embedded_tax numeric:=0;begin if not(app.has_permission('financial_reports.view') or app.has_permission('financial_reports.update')) then raise exception 'Missing financial report permission.' using errcode='42501';end if;select * into r from public.financial_reports where id=p_report_id;if r.id is null then raise exception 'Financial report not found.' using errcode='P0002';end if;select * into fp from public.financial_periods where id=r.financial_period_id;perform app.assert_canonical_financial_period(fp.id);select coalesce(sum(amount),0) into v_pay from public.finance_payments where status='confirmed' and received_at is not null and app.accounting_date(received_at) between fp.starts_on and fp.ends_on;select coalesce(sum(amount),0) into v_ref from public.finance_refunds where status='processed' and processed_at is not null and app.accounting_date(processed_at) between fp.starts_on and fp.ends_on;v_rev:=greatest(v_pay-v_ref,0);select coalesce(sum(total_amount) filter(where cost_class='direct_cost'),0),coalesce(sum(total_amount) filter(where cost_class='agent_fee'),0),coalesce(sum(total_amount) filter(where cost_class='partner_fee'),0),coalesce(sum(total_amount) filter(where cost_class='marketing_fee'),0),coalesce(sum(total_amount) filter(where cost_class='payment_fee'),0),coalesce(sum(total_amount) filter(where cost_class='operating_expense'),0),coalesce(sum(total_amount) filter(where cost_class='tax'),0),coalesce(sum(total_amount) filter(where cost_class='other'),0),coalesce(sum(total_amount),0),coalesce(sum(tax_amount),0) into v_hpp,v_agent,v_partner,v_marketing,v_payment,v_opex,v_tax,v_other,v_exp,v_embedded_tax from public.finance_expenses where status='recorded' and expense_on between fp.starts_on and fp.ends_on;return jsonb_build_object('period_start',fp.starts_on,'period_end',fp.ends_on,'confirmed_payments',v_pay,'processed_refunds',v_ref,'net_revenue',v_rev,'hpp',v_hpp,'gross_profit',v_rev-v_hpp,'agent_fee',v_agent,'partner_fee',v_partner,'marketing_fee',v_marketing,'payment_fee',v_payment,'operating_expense',v_opex,'tax_expense',v_tax,'other_expense',v_other,'embedded_tax_amount',v_embedded_tax,'expense_total',v_exp,'net_profit',v_rev-v_exp,'gross_margin_percent',case when v_rev>0 then round(((v_rev-v_hpp)/v_rev)*100,2) else 0 end,'net_margin_percent',case when v_rev>0 then round(((v_rev-v_exp)/v_rev)*100,2) else 0 end);end$$;revoke all on function app.financial_report_profit_loss_breakdown(uuid) from public,anon;grant execute on function app.financial_report_profit_loss_breakdown(uuid) to authenticated;